export function buildSenses(g,T,{kind='eye',state='far'}={}){const ball=(p,scale,c,name)=>{let m=new T.Mesh(new T.SphereGeometry(1,40,28),new T.MeshStandardMaterial({color:c,roughness:.35}));m.position.set(...p);m.scale.set(...scale);m.name=name;g.add(m);return m;};
if(kind==='brain'){for(let side of[-1,1]){ball([0,.3,side*.43],[1.55,1.04,.52],0xc8958b,'cerebral-cortex');for(let j=0;j<9;j++){let x=-1.25+j*.3,pts=[];for(let i=0;i<=28;i++){let a=-1.15+i*2.3/28,xx=x+.09*Math.sin(a*9+j),rr=Math.sqrt(Math.max(.08,1-xx*xx/(1.55*1.55)));pts.push(new T.Vector3(xx,.3+1.045*rr*Math.sin(a),side*(.43+.525*rr*Math.cos(a))));}let tube=new T.Mesh(new T.TubeGeometry(new T.CatmullRomCurve3(pts),40,.018,8,false),new T.MeshStandardMaterial({color:0x9a6f70,roughness:.6}));tube.name='cortical-fold';g.add(tube);}}ball([1,-.65,0],[.62,.45,.64],0x9fbcbf,'cerebellum');for(let j=0;j<6;j++){let y=-.98+j*.11,pts=[];for(let i=0;i<=24;i++){let a=i*Math.PI*2/24;pts.push(new T.Vector3(1+.55*Math.cos(a),y,.58*Math.sin(a)));}g.add(new T.Mesh(new T.TubeGeometry(new T.CatmullRomCurve3(pts),32,.014,6,false),new T.MeshStandardMaterial({color:0x71969e})));}let stem=ball([.45,-1.13,0],[.2,.6,.22],0xd7b991,'medulla');stem.rotation.z=.15;return;}
// Front-open globe: the hemisphere is a cutaway, not a transparent whole sphere.
let shell=new T.Mesh(new T.SphereGeometry(1.45,48,32,Math.PI,Math.PI),new T.MeshStandardMaterial({color:0xe0d6c8,side:T.DoubleSide,roughness:.4}));shell.name='sclera-cutaway';g.add(shell);let retina=new T.Mesh(new T.SphereGeometry(1.38,48,32,Math.PI,Math.PI),new T.MeshStandardMaterial({color:0xc48b83,side:T.DoubleSide,roughness:.45}));retina.name='retina';g.add(retina);ball([-1.15,0,.05],[.12,.58,.58],0x8db3bc,'cornea');ball([-.75,0,.15],[.09,.52,.5],0x456d80,'iris');ball([-.52,0,.25],[state==='near'?.24:.13,.5,.43],0xb5d5da,'lens');ball([1.5,-.22,-.15],[.6,.16,.16],0xd2b99b,'optic-nerve');for(let sign of[-1,1]){ball([-.54,sign*.65,.15],[.25,.1,.18],0xbc8f8d,'ciliary-muscle');let rod=new T.Mesh(new T.CylinderGeometry(.02,.02,.23,12),new T.MeshStandardMaterial({color:0xd7c7ac}));rod.position.set(-.52,sign*.53,.2);rod.name='suspensory-ligament';g.add(rod);}}
